ALTER TABLE public.files DROP CONSTRAINT files_check, DROP CONSTRAINT files_purpose_check; ALTER TABLE public.files ADD CONSTRAINT files_entity_check CHECK(num_nonnulls(offer_id,demand_id,item_id,spy_id,profile_id)=1), ADD CONSTRAINT files_purpose_extended_check CHECK(purpose IN ('reference','final','product','avatar'));
CREATE OR REPLACE FUNCTION public.notify_publication() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE target_item uuid; BEGIN SELECT item_id INTO target_item FROM public.creative_versions WHERE id=new.version_id; INSERT INTO public.notifications(user_id,item_id,title,body) SELECT user_id,target_item,'Publicação registrada',new.campaign FROM public.user_roles WHERE role='admin'; RETURN new; END $$;
CREATE TRIGGER publications_notify AFTER INSERT ON public.publications FOR EACH ROW EXECUTE FUNCTION public.notify_publication();
CREATE TRIGGER performance_audit AFTER INSERT OR UPDATE ON public.performance_daily FOR EACH ROW EXECUTE FUNCTION public.log_dr_change();
CREATE TRIGGER publications_audit AFTER INSERT OR UPDATE ON public.publications FOR EACH ROW EXECUTE FUNCTION public.log_dr_change();
CREATE TRIGGER spy_audit AFTER INSERT OR UPDATE ON public.spy_references FOR EACH ROW EXECUTE FUNCTION public.log_dr_change();
ALTER TABLE public.demand_items ADD CONSTRAINT performance_status_valid CHECK(performance_status IN ('Não testado','Em teste','Vencedor','Perdedor','Pausado'));
CREATE OR REPLACE FUNCTION public.create_from_spy(reference_ids uuid[], target_offer uuid, demand_title text, target_editor uuid DEFAULT NULL, existing_demand uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SET search_path=public AS $$ DECLARE result_id uuid; ref public.spy_references; sequence_no integer; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Apenas administradores podem criar demandas'; END IF; IF cardinality(reference_ids)<1 OR cardinality(reference_ids)>100 THEN RAISE EXCEPTION 'Selecione de 1 a 100 referências'; END IF; IF existing_demand IS NULL THEN INSERT INTO public.demands(title,offer_id,kind) VALUES(demand_title,target_offer,CASE WHEN cardinality(reference_ids)=1 THEN 'individual' ELSE 'batch' END) RETURNING id INTO result_id; ELSE SELECT id INTO result_id FROM public.demands WHERE id=existing_demand AND kind='batch' FOR UPDATE; IF result_id IS NULL THEN RAISE EXCEPTION 'Selecione um lote'; END IF; END IF; SELECT coalesce(max(item_number),0) INTO sequence_no FROM public.demand_items WHERE demand_id=result_id; FOR ref IN SELECT * FROM public.spy_references WHERE id=ANY(reference_ids) LOOP sequence_no:=sequence_no+1; INSERT INTO public.demand_items(demand_id,name,item_number,assigned_to,hook,copy,instructions,language,source_spy_id) VALUES(result_id,ref.name,sequence_no,target_editor,ref.hook,ref.copy,concat_ws(E'\n',ref.notes,ref.original_url,ref.library_url),ref.language,ref.id); END LOOP; RETURN result_id; END $$;
REVOKE ALL ON FUNCTION public.create_from_spy(uuid[],uuid,text,uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.create_from_spy(uuid[],uuid,text,uuid,uuid) TO authenticated;